def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Record narrow gaps inside horizontal bars. The gap's bar color is the
    # color on its left, except at a color boundary where the right color
    # describes the bar segment extending to the right.
    events = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c + 1] != 0:
                color = row[c + 1] if row[c + 1] != row[c - 1] else row[c - 1]
                events.setdefault(c, []).append((r, color))

    for c, bars in events.items():
        bars.sort()
        # The isolated/short vertical object below the bars supplies the
        # color for the section below the last bar.
        below_color = None
        below_start = max(r for r, _ in bars) + 1
        for r in range(below_start, h):
            if grid[r][c] != 0:
                below_color = grid[r][c]
                break

        previous = -1
        for r, color in bars:
            for rr in range(previous + 1, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color
            previous = r

        if below_color is not None:
            for rr in range(previous + 1, h):
                if out[rr][c] == 0:
                    out[rr][c] = below_color

    return out
